import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"噬嗑","description":"周易集解 - 噬嗑","frontmatter":{"title":"噬嗑","description":"周易集解 - 噬嗑"},"headers":[],"relativePath":"classics/jijie/021.md","filePath":"classics/jijie/021.md"}'),l={name:"classics/jijie/021.md"};function n(d,a,t,p,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="噬嗑" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑" aria-label="Permalink to “噬嗑”">​</a></h1><h2 id="噬嗑-1" tabindex="-1">噬嗑 <a class="header-anchor" href="#噬嗑-1" aria-label="Permalink to “噬嗑”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>噬嗑，享，利用獄。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：可觀而後有所合，故受之以噬嗑。嗑者，合也。</p><p>崔憬曰：言可觀政於人，則有所合於刑矣，故曰｢可觀而有所合｣。</p><p>虞翻曰：否五之坤初，坤初之五，剛柔交，故亨也。坎為獄，艮為手，離為明，四以不正，而係於獄。上當之三，蔽四成豐，折獄致刑，故利用獄。坤為用也。</p><p>案：頤中有物曰噬嗑，謂九四也。四互坎體，坎為法律，又為刑獄，四在頤中，齧而後亨。故利用獄也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：頤中有物，曰噬嗑。噬嗑而亨。剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>虞翻曰：物謂四，則所噬乾脯也。頤中無物，則口不噬。故先舉頤中有物曰噬嗑也。</p><p>崔憬曰：物在頤中，隔其上下，因齧而合，乃得其亨焉。以喻人於上下之間，有亂群者，當用刑去之，故言利用獄。</p><p>盧氏曰：此本否卦。乾之九五，分降坤初；坤之初六，分升乾五，是剛柔分也。分則雷動於下，電照於上，合成天威，故曰｢雷電合而成章｣也。</p><p>侯果曰：坤之初六，上升乾五，是柔得中而上行。雖則失位，文明以中，斷制枉直，不失情理，故｢利用獄｣。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：雷電，噬嗑。先王以明罰勑法。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>宋衷曰：雷動而威，電動而明，二者合而其道章也。用刑之道，威明相兼。若威而不明，恐致淫濫；明而無威，不能伏物。故須雷電竝合，而噬嗑備。</p><p>侯果曰：雷所以動物，電所以照物。雷電震照，則萬物不能懷邪。故先王則之，明罰勑法，以示萬物，欲萬方一心也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，屨校滅趾，無咎。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>虞翻曰：屨，貫。趾，足也。震為足，坎為校；震沒坎下，故｢屨校滅趾｣。初位得正，故無咎。</p><p>乾寶曰：趾，足也。屨校，貫械也。初居剛躁之家，體貪狼之性，以震掩巽，強暴之男也。行侵陵之罪，以陷屨校之刑，故曰｢屨校滅趾｣。得位於初，顧震知懼，小懲大戒，以免刑戮，故曰無咎矣。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：屨校滅趾，不行也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：否坤小人。以陰消陽，其亡其亡。故五變滅初，否殺不行也。</p><p>乾寶曰：不敢遂行強也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，噬膚滅鼻，無咎。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>虞翻曰：噬，食也。艮為膚，為鼻；鼻沒坎水中，隱藏不見，故｢噬膚滅鼻｣。乘剛，又得正多譽，故無咎。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：噬膚滅鼻，乘剛也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>侯果曰：居中履正，用刑者也。二互體艮。艮為鼻，又為黔喙，噬膚滅鼻之象也。乘剛，噬必深，噬過其分，故滅鼻也。刑刻雖峻，得所疾也。雖則滅鼻，而無咎矣。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，噬臘肉，遇毒，小吝，無咎。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：三在膚裡，故稱肉。離日熯之，為臘；坎為毒，故｢噬臘肉遇毒｣。毒謂矢毒也。失位承四，故小吝。與上易位，利用獄成豐，故無咎也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：遇毒，位不當也。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：臘肉，謂四也。三以不正，噬取異家，法當遇罪，故曰遇毒。為艮所止，所欲不得，故小吝也。所欲不得，則免於罪，故無咎矣。</p><h2 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h2><p>九四，噬乾胏，得金矢，利艱貞，吉。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：利艱貞吉，未光也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>陸績曰：肉有骨，謂之胏。離為乾肉，又為兵矢。失位用刑，物亦不服。若噬有骨之乾胏也。金矢者，取其剛直也。噬胏雖復艱難，終得申其剛直，雖獲正吉，未為光大也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，噬乾肉，得黃金，貞厲，無咎。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>虞翻曰：陰稱肉，位當離，日中烈，故乾肉也。乾金黃，故得黃金。貞，正。厲，危也。變而得正，故無咎。</p><p>王弼曰：乾肉，堅也。黃，中。金，剛也。以陰處陽，以柔承剛，以噬於物，物亦不服，故曰｢噬乾肉｣也。然處得尊位，而居於中，能行其戮也。履不正而能行其戮，剛勝者也。噬雖不服，得中而勝，故曰｢噬乾肉得黃金｣也。己雖不正，而刑戮得當，故雖貞厲而無咎也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：貞厲無咎，得當也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：謂陰來正居，是而厲陽也。以陰厲陽，正居其處。而無咎者，以從下明上，不失其中。所言得當。</p><h2 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h2><p>上九，何校滅耳，兇。</p><h2 id="上九注" tabindex="-1">上九注 <a class="header-anchor" href="#上九注" aria-label="Permalink to “上九注”">​</a></h2><p>荀爽曰：為五所何，故曰何校。據五應三，欲盡滅坎。上體坎，為耳。故曰滅耳兇。上以不正，侵欲無已，奪取異家，惡積而不可掩，罪大而不可解，故宜兇矣。</p><p>鄭玄曰：離為藁木；坎為耳，木在耳上，何校滅耳之象也。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：何校滅耳，聰不明也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>《九家易》曰：當據離坎，以為聰明。坎既不正，今欲滅之。故曰｢聰不明也｣。</p>',71)])])}const f=e(l,[["render",n]]);export{b as __pageData,f as default};
